.nav-link.active-page {
  position: relative;
  color: #4c2f10; 
  font-weight: 600;
}

.nav-link.active-page::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 2px;
  background-color:#4c2f10; 
  border-radius: 2px;
  animation: slideIn 0.3s ease-in-out;
}

@keyframes slideIn {
  from {
    width: 0;
  }
  to {
    width: 100%;
  }
}

.navbar-menu {
